from scipy.optimize import least_squares
def fit(f,p0,n=30):
    best=None
    rng=np.random.default_rng(0)
    for _ in range(n):
        x0=np.array(p0)*(1+0.5*rng.standard_normal(len(p0)))if _>0 else np.array(p0)
        try:
            r=least_squares(lambda p: f(p)-sigma,x0,max_nfev=3000)
            if best is None or r.cost<best.cost: best=r
        except Exception as ex: pass
    return best, 2*best.cost/np.sum((sigma-sigma.mean())**2)
